const pages=['Aim','Theory','Procedure','Pretest','Demo','Practice','Posttest'];
const main=document.querySelector('main');let data=[],runs=[],timer=null,current=null,history=[],w=0,b=0,iteration=0;
const source='https://www.kaggle.com/datasets/ashydv/advertising-dataset';
const ready=fetch('data/advertising.csv').then(r=>{if(!r.ok)throw Error('Dataset unavailable');return r.text()}).then(t=>{const lines=t.trim().split(/\r?\n/),heads=lines.shift().split(',').map(s=>s.trim());data=lines.map(l=>{let v=l.split(',').map(Number);return{x:v[heads.indexOf('TV')],y:v[heads.indexOf('Sales')]}});if(data.some(d=>!Number.isFinite(d.x)||!Number.isFinite(d.y)))throw Error('Invalid dataset');return data});
document.querySelector('#nav').innerHTML=pages.map((p,i)=>`<a href="#${p.toLowerCase()}" data-page="${p.toLowerCase()}"><em>0${i+1}</em>${p}<span style="margin-left:auto">${p==='Demo'?'↗':''}</span></a>`).join('');
const intro=(label,title,sub)=>`<div class="eyebrow">EXPERIMENT 01 · ${label}</div><div class="heading"><h1>${title}</h1><span class="section-tag">Machine Learning Lab</span></div><p class="subtitle">${sub}</p>`;
const bottom=(prev,next)=>`<div class="bottom-nav"><span>${prev?`<a href="#${prev.toLowerCase()}">← ${prev}</a>`:'Estimated time: 25–35 minutes'}</span>${next?`<a class="button" href="#${next.toLowerCase()}">${next==='Theory'?'Explore the theory':`Continue to ${next}`} &nbsp; →</a>`:''}</div>`;
function illustration(){return `<svg viewBox="0 0 410 260" aria-label="Gradient descent moving down a loss curve" role="img"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#dfc9cc" stroke-width=".6"/></pattern><linearGradient id="fill" x2="0" y2="1"><stop stop-color="#e5a3be" stop-opacity=".4"/><stop offset="1" stop-color="#fff1d0" stop-opacity=".1"/></linearGradient></defs><rect x="20" y="15" width="360" height="220" fill="url(#grid)"/><path d="M45 45 Q195 350 365 40 L365 230 H45Z" fill="url(#fill)"/><path d="M45 45 Q195 350 365 40" fill="none" stroke="#b83465" stroke-width="3"/><path d="M45 235H385 M30 240V20" stroke="#bda4ad" fill="none"/><g fill="#b83465" stroke="#fff5db" stroke-width="3"><circle cx="65" cy="81" r="7"/><circle cx="101" cy="132" r="7"/><circle cx="139" cy="167" r="7"/><circle cx="171" cy="188" r="7"/><circle cx="195" cy="196" r="7"/></g><circle cx="209" cy="197" r="11" fill="#f4d35e" stroke="#b58a2f" stroke-width="2"/><path d="M65 81L101 132 139 167 171 188 195 196" fill="none" stroke="#b83465" stroke-dasharray="4 5"/><text x="274" y="30" fill="#8b6174" font-size="12">Loss J(θ)</text><text x="275" y="254" fill="#8b6174" font-size="11">Model parameter θ →</text><text x="226" y="211" fill="#8b6c19" font-size="11">minimum</text></svg>`}
function render(){clearInterval(timer);timer=null;const page=location.hash.slice(1).toLowerCase()||'aim';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));
if(page==='aim')main.innerHTML=intro('GET STARTED','Small steps. Better predictions.','Discover how machines learn by minimizing error — one gradient descent step at a time.')+`<section class="hero"><div class="hero-copy"><span class="badge">THE AIM</span><h2>Find the minimum.<br>Understand the journey.</h2><p>Implement gradient descent on a real dataset and investigate how learning rate shapes convergence and optimization performance.</p><a class="button" href="#demo">Launch experiment &nbsp; ↗</a></div><div class="hero-art">${illustration()}<span class="art-note">θ ← θ − α ∇J(θ)</span></div></section><div class="meta"><span><strong>◷</strong> 25–35 minutes</span><span><strong>◈</strong> Beginner friendly</span><span><strong>⌘</strong> Linear regression</span><span><strong>↗</strong> Real Kaggle data</span></div><div class="section-head"><h2>What you’ll learn</h2><span>Three ideas. One experiment.</span></div><section class="grid"><article class="card"><div class="icon">∇</div><h3>Understand the descent</h3><p>Connect gradients, parameter updates, and the loss function to see how a model learns.</p></article><article class="card"><div class="icon">↗</div><h3>Find your learning rate</h3><p>Explore slow progress, stable convergence, and divergence by changing the step size.</p></article><article class="card"><div class="icon">⌁</div><h3>Measure performance</h3><p>Compare loss, iterations, and prediction error against a least-squares benchmark.</p></article></section><div class="dataset"><div class="icon" style="background:#f9e9ab;color:#927626">▦</div><div><h3>A real dataset. A tangible problem.</h3><p>Kaggle Advertising · 200 observations · TV spend → Sales<br>Fit a line and discover how optimization turns data into predictions.</p></div><a href="${source}" target="_blank" rel="noreferrer">View dataset ↗</a></div>`+bottom(null,'Theory');
else if(page==='theory')main.innerHTML=intro('THE CONCEPT','Learning, one update at a time.','The mathematics behind the experiment, connected to the model you will train.')+`<div class="prose"><h2>01 / A line that learns</h2><p>We predict sales from TV advertising spend using ŷ = wx + b. The slope w and intercept b are the parameters. Gradient descent repeatedly adjusts both to reduce prediction error.</p><h2>02 / Measure the error</h2><div class="formula">J(w,b) = (1 / 2n) Σ (wxᵢ + b − yᵢ)²</div><p>This is half the mean squared error. Smaller values indicate a closer fit on the selected dataset. The irreducible error may remain positive: a straight line does not explain every observation.</p><h2>03 / Follow the negative gradient</h2><div class="formula">∂J/∂w = (1/n) Σ (ŷᵢ − yᵢ)xᵢ<br><br>∂J/∂b = (1/n) Σ (ŷᵢ − yᵢ)<br><br>w ← w − α ∂J/∂w &nbsp; b ← b − α ∂J/∂b</div><p>Compute both gradients using the current parameters, then update them simultaneously. The learning rate α controls the size of each step.</p><h2>04 / Why learning rate matters</h2><p>A small α moves cautiously and can require many iterations. A suitable α converges efficiently. An excessive α can oscillate or diverge. For this quadratic objective, stable fixed-step convergence requires 0 &lt; α &lt; 2/λmax(H), where H is the loss Hessian.</p><h2>05 / Scale and evaluate</h2><p>The demo standardizes TV spend by default: x′ = (x − mean(x)) / std(x). Sales remains in its original units. This improves conditioning and makes learning rates easier to explore. With standardized x, this objective has a stability boundary at α = 2.</p><p>The experiment reports training RMSE, half-MSE loss, and the gap to the analytical least-squares optimum. It uses all 200 rows to study optimization; these metrics do not estimate performance on unseen data.</p></div>`+bottom('Aim','Procedure');
else if(page==='procedure')main.innerHTML=intro('THE WORKFLOW','Your route to the minimum.','Follow these steps, then change one setting at a time to make a fair comparison.')+`<div class="steps">${[['Inspect the dataset','Use the Kaggle Advertising data. TV spend is the input and Sales is the target; Radio and Newspaper are not used in this univariate experiment.'],['Set a baseline','Open Demo. Keep standardization enabled, choose α = 0.05, and use a budget of 200 iterations. Both parameters start at zero.'],['Run and observe','Watch the loss curve and fitted line change. Pause to inspect a step, or advance one iteration at a time.'],['Compare learning rates','Use Practice to compare α = 0.005, 0.05, and 0.5 under the same settings. Then try 2.1 to observe divergence with standardized inputs.'],['Investigate feature scaling','Disable standardization and try α = 0.05. Reset, then try 0.00001. Large unscaled inputs require much smaller steps.'],['Evaluate and reflect','Compare final loss, training RMSE, iteration count, and the gap from least squares. Complete the Posttest to check your understanding.']].map((s,i)=>`<div class="step"><span>0${i+1}</span><div><h3>${s[0]}</h3><p>${s[1]}</p></div></div>`).join('')}</div>`+bottom('Theory','Pretest');
else if(page==='pretest'||page==='posttest')quiz(page);
else if(page==='demo'||page==='practice')experiment(page);
else {location.hash='aim';return}window.scrollTo(0,0)}
const quizzes={pretest:[['What does gradient descent minimize?',['The loss function','The number of observations','The input values'],0,'The loss measures prediction error; gradient descent adjusts parameters to reduce it.'],['Which direction is used for a descent update?',['Along the gradient','Opposite the gradient','A random direction every time'],1,'The negative gradient points toward the steepest local decrease.'],['What does the learning rate control?',['The size of each parameter update','The dataset size','The number of features'],0,'The learning rate scales the gradient at each step.']],posttest:[['With standardized TV input, what happens at α = 2.1 in this lab?',['Guaranteed rapid convergence','The loss generally diverges','The data is deleted'],1,'The stability boundary is α = 2 for this standardized univariate half-MSE objective.'],['Why standardize TV spend?',['To improve conditioning and learning-rate stability','To force the loss to zero','To add more observations'],0,'Scaling changes the geometry of optimization without changing the family of fitted lines.'],['A very small loss gap to least squares means…',['The optimizer is close to the best linear fit on these rows','The model will predict all unseen data perfectly','The loss must be zero'],0,'The benchmark measures optimization quality on the training data, not generalization.'],['Which is the fairest learning-rate comparison?',['Change rate, scaling, and iterations together','Keep data, scaling, initialization, and budget fixed','Use different datasets for each rate'],1,'Holding other conditions fixed isolates the effect of the learning rate.'],['How should w and b be updated?',['Use the new w to compute the same-step b gradient','Compute both gradients first, then update together','Only update the intercept'],1,'Simultaneous updates use both derivatives at the same current parameter vector.']]};
function quiz(type){let q=quizzes[type];main.innerHTML=intro(type==='pretest'?'CHECK YOUR STARTING POINT':'CHECK YOUR UNDERSTANDING',type==='pretest'?'Before you begin.':'Put your learning to the test.',`${q.length} questions · Choose one answer for each question. Feedback appears after you submit.`)+`<form id="quiz">${q.map((a,i)=>`<div class="question"><h3>${i+1}. ${a[0]}</h3>${a[1].map((v,j)=>`<label class="option"><input type="radio" name="q${i}" value="${j}" required> &nbsp;${v}</label>`).join('')}<div id="f${i}" class="feedback"></div></div>`).join('')}<button>Check answers →</button> <span id="score" role="status"></span></form>`+bottom(type==='pretest'?'Procedure':'Practice',type==='pretest'?'Demo':null);document.querySelector('#quiz').onsubmit=e=>{e.preventDefault();let score=0;q.forEach((a,i)=>{const correct=Number(new FormData(e.target).get('q'+i))===a[2];score+=correct;document.querySelector('#f'+i).textContent=(correct?'Correct. ':'Review: ')+a[3]});document.querySelector('#score').textContent=` ${score} / ${q.length} correct`;}}
function experiment(page){main.innerHTML=intro(page==='demo'?'THE INTERACTIVE LAB':'YOUR EXPERIMENT SPACE',page==='demo'?'Watch the learning happen.':'Change a variable. Find a pattern.',page==='demo'?'Train a linear model on real Kaggle data. Adjust the learning rate and see each update take shape.':'Run controlled experiments, compare outcomes, and export your observations.')+`<div class="experiment"><section class="card controls"><div><h3 style="margin-top:0">Experiment settings</h3><label for="rate">Learning rate (α)</label><input id="rate" type="number" value="0.05" min="0.0000001" max="10" step="any"><label for="budget">Iteration budget</label><input id="budget" type="number" value="200" min="1" max="5000" step="1"><label><input id="scale" type="checkbox" checked> Standardize TV spend</label><p>Initial slope = 0<br>Initial intercept = 0</p></div><div><button id="run">▶ Run experiment</button> <button class="secondary" id="step">Single step</button> <button class="secondary" id="reset">↺ Reset</button><div class="notice">${page==='practice'?'Try α = 0.005, 0.05, 0.5, then 2.1. Keep scaling and budget fixed.':'200 Kaggle observations. Full-batch updates. Sales stays in original units.'}</div><p id="status" role="status">Loading dataset…</p></div></section><div><div class="stats"><div class="stat"><small>ITERATIONS</small><b id="iterations">0</b></div><div class="stat"><small>LOSS · ½ MSE</small><b id="loss">—</b></div><div class="stat"><small>TRAINING RMSE</small><b id="rmse">—</b></div></div><section class="card"><h3 style="margin-top:0">The convergence curve</h3><div class="legend"><span style="color:#b83465">━ Gradient descent</span><span>Loss vs. iteration · log scale</span></div><svg id="loss-chart" class="chart" viewBox="0 0 600 230" role="img" aria-label="Loss over iterations"></svg></section><section class="card" style="margin-top:16px"><h3 style="margin-top:0">From data to a fitted line</h3><div class="legend"><span>● Observed sales</span><span style="color:#b83465">━ Prediction</span><span>TV spend → Sales</span></div><svg id="fit-chart" class="chart" viewBox="0 0 600 230" role="img" aria-label="TV advertising versus sales with fitted line"></svg><p id="model"></p></section></div></div><section class="card" style="margin-top:24px"><div class="section-head" style="margin:0"><h3>Experiment notebook</h3><button id="export" class="secondary">Download results ↓</button></div><p>Completed runs stay here during this visit. Loss gap is measured against the analytical least-squares optimum.</p><div class="scroll"><table><thead><tr><th>α</th><th>Scaling</th><th>Iterations</th><th>Final loss</th><th>Loss gap</th><th>Outcome</th></tr></thead><tbody id="runs"></tbody></table></div></section><div class="dataset"><div><h3>Dataset & methodology</h3><p>All 200 rows · TV → Sales · Full-batch gradient descent · No train/test split (optimization experiment)<br>Convergence: gradient norm &lt; 10⁻⁶. Numerical stop: nonfinite values or loss &gt; 10¹².</p></div><a href="data/advertising.csv" download>Download dataset ↓</a><a href="${source}" target="_blank" rel="noreferrer">Kaggle source ↗</a></div>`+bottom(page==='demo'?'Pretest':'Demo',page==='demo'?'Practice':'Posttest');
document.querySelector('#run').onclick=()=>{if(timer){clearInterval(timer);timer=null;document.querySelector('#run').textContent='▶ Resume';setStatus('Paused. Advance one step or resume.');return}if(!current||current.done){if(!reset())return}document.querySelector('#run').textContent='Ⅱ Pause';timer=setInterval(()=>{for(let i=0;i<2&&current&&!current.done;i++)advance();draw();},35)};
document.querySelector('#step').onclick=()=>{clearInterval(timer);timer=null;if(!current||current.done){if(!reset())return}advance();draw();if(!current.done)document.querySelector('#run').textContent='▶ Resume'};document.querySelector('#reset').onclick=reset;['rate','budget','scale'].forEach(id=>document.querySelector('#'+id).onchange=()=>{clearInterval(timer);timer=null;current=null;document.querySelector('#run').textContent='▶ Run experiment';setStatus('Settings changed. Start a new run.');});document.querySelector('#export').onclick=()=>{if(!runs.length){setStatus('Complete a run to export results.');return}const blob=new Blob(['learning_rate,standardized,iterations,loss,loss_gap,outcome\n'+runs.map(r=>[r.rate,r.scale,r.iterations,r.loss,r.gap,r.outcome].join(',')).join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='gradient-lab-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};table();ready.then(()=>{if(document.querySelector('#loss-chart'))reset()}).catch(e=>setStatus(e.message));}
function setStatus(s){const el=document.querySelector('#status');if(el)el.textContent=s}
function reset(){clearInterval(timer);timer=null;if(!data.length){setStatus('Dataset not loaded. Please try again.');return false}let rate=Number(document.querySelector('#rate').value),budget=Number(document.querySelector('#budget').value),scale=document.querySelector('#scale').checked;if(!(rate>0&&rate<=10&&Number.isInteger(budget)&&budget>=1&&budget<=5000)){setStatus('Enter α above 0 and at most 10, and a whole iteration budget from 1 to 5000.');return false}let mean=data.reduce((s,d)=>s+d.x,0)/data.length,std=Math.sqrt(data.reduce((s,d)=>s+(d.x-mean)**2,0)/data.length);let xs=data.map(d=>scale?(d.x-mean)/std:d.x),my=data.reduce((s,d)=>s+d.y,0)/data.length,mx=xs.reduce((s,x)=>s+x,0)/xs.length;let ow=xs.reduce((s,x,i)=>s+(x-mx)*(data[i].y-my),0)/xs.reduce((s,x)=>s+(x-mx)**2,0),ob=my-ow*mx;current={rate,budget,scale,mean,std,xs,opt:calcLoss(ow,ob,xs),done:false};w=b=iteration=0;history=[calcLoss(w,b,xs)];document.querySelector('#run').textContent='▶ Run experiment';setStatus('Ready. Start your descent.');draw();return true}
function calcLoss(a,c,xs){return xs.reduce((s,x,i)=>s+(a*x+c-data[i].y)**2,0)/(2*xs.length)}
function advance(){let c=current;if(!c||c.done)return;let dw=0,db=0;for(let i=0;i<data.length;i++){let e=w*c.xs[i]+b-data[i].y;dw+=e*c.xs[i]/data.length;db+=e/data.length}if(Math.hypot(dw,db)<1e-6){finish('Converged');return}w-=c.rate*dw;b-=c.rate*db;iteration++;let loss=calcLoss(w,b,c.xs);history.push(loss);if(!Number.isFinite(loss)||loss>1e12){finish('Diverged');return}if(iteration>=c.budget)finish('Budget reached')}
function finish(outcome){current.done=true;clearInterval(timer);timer=null;const loss=history.at(-1);runs.push({rate:current.rate,scale:current.scale,iterations:iteration,loss,gap:Math.max(0,loss-current.opt),outcome});setStatus(outcome==='Converged'?'Converged: gradient norm is below 10⁻⁶.':outcome==='Diverged'?'Diverged. Reduce α or enable standardization.':'Iteration budget reached. Compare the loss gap or allow more steps.');document.querySelector('#run').textContent='▶ Run again';table()}
const fmt=n=>!Number.isFinite(n)?'∞':Math.abs(n)>=10000?n.toExponential(2):n.toFixed(4);
function table(){const el=document.querySelector('#runs');if(el)el.innerHTML=runs.length?runs.map(r=>`<tr><td>${r.rate}</td><td>${r.scale?'On':'Off'}</td><td>${r.iterations}</td><td>${fmt(r.loss)}</td><td>${fmt(r.gap)}</td><td>${r.outcome}</td></tr>`).join(''):'<tr><td colspan="6">Your completed experiments will appear here.</td></tr>'}
function axes(xlabel,ylabel){return `<path d="M48 12V195H580" fill="none" stroke="#d5cdd3"/><text x="48" y="10" font-size="10" fill="#8c808c">${ylabel}</text><text x="490" y="224" font-size="10" fill="#8c808c">${xlabel}</text>`}
function draw(){if(!current)return;let c=current,loss=history.at(-1);document.querySelector('#iterations').textContent=iteration;document.querySelector('#loss').textContent=fmt(loss);document.querySelector('#rmse').textContent=fmt(Math.sqrt(loss*2));const logs=history.map(v=>Math.log10(Math.max(v,1e-12))),lo=Math.floor(Math.min(...logs)),hi=Math.max(lo+1,Math.ceil(Math.max(...logs)));let path=logs.map((v,i)=>`${i?'L':'M'}${48+532*i/Math.max(1,c.budget)} ${195-170*(v-lo)/(hi-lo)}`).join(' ');document.querySelector('#loss-chart').innerHTML=axes('Iteration','Loss (log₁₀)')+Array.from({length:4},(_,i)=>{let y=195-i*55;return `<path d="M48 ${y}H580" stroke="#f0e9ed"/><text x="0" y="${y+4}" font-size="10" fill="#8c808c">${(lo+i*(hi-lo)/3).toFixed(1)}</text>`}).join('')+`<path d="${path}" fill="none" stroke="#b83465" stroke-width="2.5"/><text x="48" y="210" font-size="10" fill="#8c808c">0</text><text x="564" y="210" font-size="10" fill="#8c808c">${c.budget}</text>`;
let rawW=c.scale?w/c.std:w,rawB=c.scale?b-w*c.mean/c.std:b;let line=[rawB,rawW*300+rawB];let points=data.map(d=>`<circle cx="${48+d.x/300*532}" cy="${195-d.y/30*170}" r="2.7" fill="#be9caa" opacity=".65"/>`).join('');document.querySelector('#fit-chart').innerHTML=`<defs><clipPath id="clip"><rect x="48" y="12" width="532" height="183"/></clipPath></defs>`+axes('TV advertising spend','Sales')+`<g clip-path="url(#clip)">${points}<path d="M48 ${195-line[0]/30*170}L580 ${195-line[1]/30*170}" stroke="#b83465" stroke-width="2.5"/></g><text x="30" y="198" font-size="10" fill="#8c808c">0</text><text x="25" y="28" font-size="10" fill="#8c808c">30</text><text x="48" y="210" font-size="10" fill="#8c808c">0</text><text x="560" y="210" font-size="10" fill="#8c808c">300</text>`;document.querySelector('#model').textContent=`Original-unit model: Sales = ${fmt(rawW)} × TV + ${fmt(rawB)} · Optimum loss: ${fmt(c.opt)} · Gap: ${fmt(Math.max(0,loss-c.opt))}`;}
window.addEventListener('hashchange',render);render();
